import pathlib,json,statistics as st,html,hashlib,zipfile,datetime
from analyze import summarize
P=pathlib.Path('dev/phase13');D=pathlib.Path('dist/audits');D.mkdir(exist_ok=True)
refs=json.load(open(P/'real-seasons.json'));trans=json.load(open(P/'real-transition.json'));freeze=json.load(open(P/'freeze.json'));run=json.load(open(P/'holdout-run.json'));decision=json.load(open(P/'decision.json'))
assert len(run['completed'])==20 and not run['failures'] and run['hashesUnchanged']
for f,h in freeze['files'].items():assert hashlib.sha256(pathlib.Path(f).read_bytes()).hexdigest()==h,f
scores={league:summarize('holdout',league)for league in ['nba','wnba']}
assert all(v['pooled']['seasons']==10 for v in scores.values())
assert scores['nba']['pooled']['games']==12300 and scores['wnba']['pooled']['games']==2400
metrics=[('meanMargin','Mean winning margin','points'),('blow20Pct','20+ point wins','%'),('within5Pct','Within 5 points','%'),('otPct','Games reaching OT','%'),('teamMarginSD','Team season mean-margin SD','points'),('fastbreakFGAPct','Transition: fast-break FGA share','%'),('final60Possessions','Final-60s possession starts','starts')]
lines=['HOOPS DYNASTY — PHASE 13 FINAL HOLDOUT AUDIT',f"Frozen build SHA-256: {freeze['productionBuildSHA256']}",f"Frozen at (UTC): {freeze['frozenAtUTC']}",f"Holdout completed (UTC): {run['finishedAtUTC']}",'','Only game change: '+decision['change'],'No transition, foul-delay, hold+quick, or final-minute pace tuning. No tuning after the holdout began.','','PRE-FREEZE WNBA CALIBRATION','All arms initially used the same five existing seeds (111–115), 1,200 evolving regular-season games. The selected 1.40 setting also used five additional calibration seeds (116–120) without a parameter change, for 2,400 games total. Those seeds are not holdout seeds. Candidate selection used mean per-season team-margin SD 5.3–6.2 and pooled 20+ rate at or below 18.8811%. Individual random seasons can lie outside the target.']
for label in decision['testedLabels']:
 s=summarize(label,'wnba');a=s['pooled'];lines.append(f"{label}: mean margin {a['meanMargin']:.3f}; 20+ {a['blow20Pct']:.3f}%; OT {a['otPct']:.3f}%; mean team-margin SD {a['teamMarginSD']:.3f}; SD seed range {s['seedRange']['teamMarginSD'][0]:.3f}–{s['seedRange']['teamMarginSD'][1]:.3f}.")
lines+=['Selection: '+decision['reason'],'','REAL FULL-SEASON REFERENCES (REGULAR SEASON, OT INCLUDED)','League | Season | Games | Mean margin | 20+ % | Within5 % | OT % | Team-margin SD']
for league,rows in refs.items():
 for r in rows:lines.append(f"{league.upper()} | {r['season']} | {r['games']} | {r['meanMargin']:.3f} | {r['blow20Pct']:.3f} | {r['within5Pct']:.3f} | {r['otPct']:.3f} | {r['teamMarginSD']:.3f}")
lines+=['','TRANSITION DEFINITION CHECK — COMPLETED BEFORE FREEZE',f"NBA same 134 games: {trans['nba']['fastbreakFGA']:,} fastbreak-tagged FGA / {trans['nba']['FGA']:,} FGA = {trans['nba']['fastbreakFGAPct']:.3f}%.",f"Retained official NBA Synergy 2024–25: team average {trans['synergyNBA']['meanTeamTransitionPossPct']:.3f}%; inferred pooled share {trans['synergyNBA']['estimatedPooledPossPct']:.3f}% ; the commonly quoted ~20% overstates the retained 2024–25 value.",f"WNBA same fastbreak-qualifier/FGA definition, 100 games in 2022–2025: {trans['wnba']['fastbreakFGA']:,} / {trans['wnba']['FGA']:,} = {trans['wnba']['fastbreakFGAPct']:.3f}%.",'The retained NBA stats.nba.com playbyplayv3 files omit qualifiers; the same 134 IDs were retrieved from the official CDN with qualifiers. Missing qualifiers were not counted as zero. Two games differ by one FGA each between feeds, cancelling in the total. One CDN final score differs by one point from the retained feed (0022400072); retaining all 134 gives 12.151%, while the 133 score-matching games give 12.123%. Both are reported; no game was dropped to improve agreement.','The 12.15% vs 18.61% comparison changes both tag definition and denominator and compares a sample to a full season. It is NOT a conversion factor. WNBA should be compared with the same PBP-tagged FGA statistic, not judged directly against Synergy possession share. Simulation tags still come from its own transition-opportunity classification, not independent real-game taggers. No official WNBA Synergy rate was available.','','FINAL HOLDOUT SCORECARDS','20 reserved seeds, not used for calibration or smoke tests; prior retained audit files checked: '+str(json.load(open(P/'reserved-seeds.json'))['priorAuditFilesChecked'])+'. Seeds were reserved before the holdout. Full evolving regular seasons; no resets or playoff games.']
for league,s in scores.items():
 a=s['pooled'];tim=json.load(open(P/f'real-timing-{league}.json'));lines+=['',league.upper()+f" — 10 seeds, {a['games']:,} games",'Metric | Holdout | 95% seed-bootstrap interval | Real reference']
 for k,title,unit in metrics:
  lo,hi=s['seedBootstrapCI95'][k]
  if k=='fastbreakFGAPct':ref=f"{trans[league][k]:.2f}% ({trans[league]['games']} PBP games)"
  elif k=='final60Possessions':ref=f"{tim['meanStartsFinal60']:.2f} ({tim['closeGames']} close / {tim['sourceGames']} PBP games)"
  else:ref=f"{min(r[k]for r in refs[league]):.2f}–{max(r[k]for r in refs[league]):.2f} {unit}"
  lines.append(f"{title} | {a[k]:.2f} {unit} | {lo:.2f}–{hi:.2f} | {ref}")
 lines += [f"Additional simulation diagnostic: transition opportunities {a['transitionOpportunityPct']:.3f}% of possession calls; this is not an official Synergy classification.",f"Final-minute sample: {a['counts']['closeGames']:,} games within six points at 60 seconds; {a['counts']['closeFinal60Starts']:,} combined-team starts. Mean team-margin SD is the mean of ten season SDs, not SD after pooling team identities across worlds.",'Per-seed results: seed | mean margin | 20+ % | within5 % | OT % | SD | fastbreak FGA % | final60 starts']
 for r in s['perSeed']:lines.append(str(r['seed'])+' | '+' | '.join(f"{r[k]:.3f}"for k,_,_ in metrics))
w=scores['wnba']['pooled'];maxblow=max(r['blow20Pct']for r in refs['wnba']);lines+=['','FINAL GATE RESULTS',f"WNBA mean season SD target 5.3–6.2: {'PASS'if 5.3<=w['teamMarginSD']<=6.2 else 'MISS'} ({w['teamMarginSD']:.3f}).",f"WNBA pooled 20+ real ceiling {maxblow:.3f}%: {'PASS'if w['blow20Pct']<=maxblow else 'MISS'} ({w['blow20Pct']:.3f}%).",f"WNBA individual seasons within SD target: {sum(5.3<=r['teamMarginSD']<=6.2 for r in scores['wnba']['perSeed'])}/10; within 20+ ceiling: {sum(r['blow20Pct']<=maxblow for r in scores['wnba']['perSeed'])}/10.",'No parameter was changed in response to these holdout results. A miss remains a miss; this report does not imply every metric or every random season is calibrated.','','DEFINITIONS AND LIMITS','Mean margin = absolute final score difference, including all OT. 20+ uses >=20; within5 uses <=5. OT = at least one overtime period. Team-margin SD = population standard deviation across teams of their signed season mean margins, computed per season then averaged.','Transition scorecard = primary FGA carrying the simulation fast-break opportunity flag divided by ALL box-score FGA, including untagged putbacks/kickouts. Real denominator = every official PBP isFieldGoal attempt, tagged numerator = qualifiers contains fastbreak, including misses. Opportunity share is a separate diagnostic.','Final60 = possession starts at 0<regulation time remaining<=60, summed across both teams, conditional on absolute margin<=6 at the 60-second checkpoint. Does not count a possession that began before the window. Real possession boundaries are reconstructed from control changes, made baskets, final made ordinary FTs, defensive rebounds and turnovers; offensive rebounds retain control. PBP is not direct inbound tracking, and inference/retained-ball edge cases can differ from the simulator.','Real full-season ranges are observed season ranges, not confidence intervals or universal pass/fail bands. PBP samples are retained convenience samples, not league censuses. Seed-cluster bootstrap uses 4,000 resamples of the ten worlds; it reflects this generated-world sample and cannot certify unseen worlds or other eras. WNBA simulated rules/size are 2024 (12 teams,40 games); 2025 real reference has13 teams,44 games.','The extra five calibration seasons were an explicitly recorded pre-freeze extension, not a second holdout; only the reserved 20 seasons are the final holdout. Calibration uses paired initial seeds, but changes can alter random-number consumption and later season paths. Aggregate differences are not isolated same-possession causal effects. Player identities, attributes, league-wide talent and position counts are preserved; roster swaps apply only to newly generated fictional modern WNBA careers. Existing saves, NBA allocation and pre-2020 generation are unchanged.','','VERIFICATION','Passive instrumentation: exact score, box and summary-event equality in six full NBA/WNBA games. Scope: player pool and positions preserved; NBA and pre-2020 allocations unchanged; loading existing rosters matches baseline normalization. Each full season asserts expected schedule count, completed non-tied final scores and box scoring identities. Frozen production and audit inputs verified before and after all holdout runs.','Production hash: '+freeze['productionBuildSHA256'],'','SOURCES AND REPRODUCTION','Official full-season game logs retained in dev/phase3, dev/phase4 and dev/phase12; file hashes in real-seasons.json.','https://stats.nba.com/stats/leaguegamelog','https://stats.wnba.com/stats/leaguegamelog','https://stats.nba.com/stats/synergyplaytypes?LeagueID=00&SeasonYear=2024-25&SeasonType=Regular%20Season&PerMode=Totals&PlayerOrTeam=T&PlayType=Transition&TypeGrouping=offensive','Official NBA tagged PBP: https://cdn.nba.com/static/json/liveData/playbyplay/playbyplay_<GAME_ID>.json; exact URLs in nba-tags-fetch.json.','Official WNBA tagged PBP: https://cdn.wnba.com/static/json/liveData/playbyplay/playbyplay_<GAME_ID>.json; sources retained from Phase12.','Reproduce from checkout: python3 dev/phase13/reference.py; node dev/phase13/run-holdout.cjs; python3 dev/phase13/analyze.py; python3 dev/phase13/report.py. Existing holdout outputs are verified/reused, not silently replaced. Deleting outputs reruns the same reserved seeds on the recorded frozen build.','The bundle includes calibration and per-game holdout outputs, protocol, frozen hashes, raw tagged/reference data, and reproduction scripts.']
text='\n'.join(lines)+'\n';pathlib.Path('docs/PHASE13-FINAL-HOLDOUT.txt').write_text(text);(D/'phase13.txt').write_text(text)
result={'frozenBuild':freeze,'decision':decision,'holdout':scores,'realSeasons':refs,'transitionReference':{k:{a:b for a,b in v.items()if a!='rows'}for k,v in trans.items()},'run':run};(P/'final-results.json').write_text(json.dumps(result,indent=2));(D/'phase13-results.json').write_text(json.dumps(result,indent=2))
(D/'phase13.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hoops Dynasty — Final holdout audit</title><style>body{max-width:1050px;margin:32px auto;padding:0 20px;background:#10151c;color:#edf2f8;font:16px/1.6 system-ui}a{color:#ffb26e}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.6 ui-monospace,monospace}</style><h1>Phase 13 · Final holdout audit</h1><p><a href="phase13.txt" download>Download full report (TXT)</a> · <a href="phase13.zip" download>Data bundle (ZIP)</a> · <a href="/">Back to Hoops Dynasty</a></p><pre>'+html.escape(text)+'</pre></html>')
